{
"predictors": 
[
  {
    "name": "Employee Satisfaction",
    "construction": "Use data from employee satisfaction surveys, normalized by company size. Higher scores indicate more satisfaction.",
    "rationale": "More satisfied employees could lead to increased productivity and higher earnings.",
    "higher_returns_for": "High values of the measure"
  },

  {
    "name": "CEO Compensation Ratio",
    "construction": "Ratio of CEO compensation to median employee compensation. Higher values indicate a larger disparity.",
    "rationale": "A large CEO pay gap could indicate potential issues with corporate governance and employee morale, possibly leading to inferior future performance.",
    "higher_returns_for": "Low values of the measure"
  },

  {
    "name": "Climate Risk Exposure",
    "construction": "Estimate of a company's potential financial loss due to climate change, such as property risk, regulatory risk, and market risk.",
    "rationale": "Firms with higher climate risk may be more likely to face financial losses, legal liabilities, and reputational harm.",
    "higher_returns_for": "Low values of the measure"
  },

  {
    "name": "Internet Presence",
    "construction": "Uses data on website traffic and search engine ranking. Higher values indicate a stronger internet presence.",
    "rationale": "Firms with a strong internet presence may have a marketing advantage, possibly leading to higher sales and earnings.",
    "higher_returns_for": "High values of the measure"
  },

  {
    "name": "Product Quality",
    "construction": "Use data on product recalls and customer reviews. Higher values indicate lower product quality.",
    "rationale": "Firms with lower product quality could face reputational harm and financial losses.",
    "higher_returns_for": "Low values of the measure"
  },

  {
    "name": "Cybersecurity Risk",
    "construction": "Data on a company's number of reported cybersecurity incidents. Higher values indicate more incidents.",
    "rationale": "Companies with weak cybersecurity may face financial losses and reputational harm.",
    "higher_returns_for": "Low values of the measure"
  },

  {
    "name": "Customer Loyalty",
    "construction": "Use customer satisfaction surveys and product repurchase rates. Higher values indicate more customer loyalty.",
    "rationale": "Firms with loyal customers may have a competitive advantage, possibly leading to higher sales and earnings.",
    "higher_returns_for": "High values of the measure"
  },

  {
    "name": "R&D Efficiency",
    "construction": "Ratio of revenue growth to research and development expenses. Higher values indicate more efficient R&D.",
    "rationale": "Firms that more efficiently convert R&D into revenue growth may outperform.",
    "higher_returns_for": "High values of the measure"
  },

  {
    "name": "Supply Chain Resilience",
    "construction": "Use data on the number and severity of supply chain disruptions. Higher values indicate more disruptions.",
    "rationale": "Firms with frequent supply chain disruptions may face operational inefficiencies and financial losses.",
    "higher_returns_for": "Low values of the measure"
  },

  {
    "name": "Diversity and Inclusion Score",
    "construction": "Use data on the diversity of a company's workforce and leadership. Higher scores indicate more diversity.",
    "rationale": "Diverse companies may have broader perspectives and better decision-making, possibly leading to superior performance.",
    "higher_returns_for": "High values of the measure"
  }
]
}
